use std::fs

fn num(s: string, width: int) -> int {
    if s.len() as int != width {
        return -1
    }
    let mut v = 0
    for c in s.chars() {
        if c < '0' || c > '9' {
            return -1
        }
        v = v * 10 + (c as int - '0' as int)
    }
    v
}

fn leap(y: int) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in(y: int, m: int) -> int {
    if m == 2 {
        if leap(y) { return 29 }
        return 28
    }
    if m == 4 || m == 6 || m == 9 || m == 11 {
        return 30
    }
    31
}

fn to_days(tok: string) -> int {
    let parts = tok.split("-").collect::<Vec<string>>()
    if parts.len() as int != 3 {
        return -1
    }
    let y = num(parts[0], 4)
    let m = num(parts[1], 2)
    let d = num(parts[2], 2)
    if y < 0 || m < 1 || m > 12 || d < 1 {
        return -1
    }
    if d > days_in(y, m) {
        return -1
    }
    let yy = if m <= 2 { y - 1 } else { y }
    let era = yy / 400
    let yoe = yy - era * 400
    let mp = (m + 9) % 12
    let doy = (153 * mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    era * 146097 + doe - 719468
}

fn main() {
    let names = ["Thursday", "Friday", "Saturday", "Sunday", "Monday", "Tuesday", "Wednesday"]
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let toks = line.split_whitespace().collect::<Vec<string>>()
        if toks.len() as int == 0 {
            continue
        }
        if toks.len() as int != 2 {
            println("invalid")
            continue
        }
        let a = to_days(toks[0])
        let b = to_days(toks[1])
        if a == -1 || b == -1 {
            println("invalid")
            continue
        }
        let lo = if a < b { a } else { b }
        let diff = if a < b { b - a } else { a - b }
        let wd = ((lo % 7) + 7) % 7
        println("${diff} ${names[wd as usize]}")
    }
}

